    A = a.values.astype(float)
    B = b.values.astype(float)
    m = np.isfinite(A) & np.isfinite(B)
    n = int(m.sum())
    if n < 50:
        return np.nan
    x = A[m]
    y = B[m]
    if x.std() == 0 or y.std() == 0:
        return np.nan
    return float(np.corrcoef(x, y)[0, 1])


def panel_key(fname, fid):
